<?php include "../auth/cek_login.php";include "../koneksi.php";$q=mysqli_query($conn,"SELECT t.*,p.nama FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id ORDER BY t.id DESC");?><!doctype html><html><head><title>Pengembalian</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Penyelesaian Transaksi</h1><table><tr><th>No</th><th>Kode</th><th>Pelanggan</th><th>Rencana</th><th>Status</th><th>Aksi</th></tr><?php $n=1;while($d=mysqli_fetch_assoc($q)):?><tr><td><?=$n++?></td><td><?=$d['kode_transaksi']?></td><td><?=$d['nama']?></td><td><?=$d['tanggal_rencana_kembali']?></td><td><?=$d['status']?></td><td><?php if($d['status']=='Disewa'):?><a href="proses.php?id=<?=$d['id']?>">Proses Pengembalian</a><?php else:?>Selesai<?php endif;?></td></tr><?php endwhile;?></table><a class="btn" href="../dashboard.php">Dashboard</a></div></body></html>